package isolation

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// The vectors file is shared with the API (breakGlass.test.ts, #10089) and
// was generated by an implementation independent of both. Keep it
// byte-identical to the API branch's copy.
func TestBreakGlassVectors(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "breakglass_vectors.json"))
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var file struct {
		Vectors []struct {
			Description string `json:"description"`
			SecretHex   string `json:"secretHex"`
			IsolationID string `json:"isolationId"`
			Generation  int    `json:"generation"`
			HourBucket  int64  `json:"hourBucket"`
			Message     string `json:"message"`
			Code        string `json:"code"`
		} `json:"vectors"`
	}
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	if len(file.Vectors) == 0 {
		t.Fatal("no vectors")
	}
	for _, v := range file.Vectors {
		t.Run(v.Description, func(t *testing.T) {
			secret, err := hex.DecodeString(v.SecretHex)
			if err != nil {
				t.Fatal(err)
			}
			if got := breakGlassMessage(v.IsolationID, v.Generation, v.HourBucket); got != v.Message {
				t.Fatalf("message = %q, want %q", got, v.Message)
			}
			code, err := BreakGlassCode(secret, v.IsolationID, v.Generation, v.HourBucket)
			if err != nil {
				t.Fatalf("BreakGlassCode: %v", err)
			}
			if code != v.Code {
				t.Fatalf("code = %q, want %q", code, v.Code)
			}
		})
	}
}

func TestBreakGlassCodeRejectsBadInput(t *testing.T) {
	secret := make([]byte, 32)
	cases := []struct {
		name   string
		secret []byte
		id     string
		gen    int
		bucket int64
	}{
		{"short secret", make([]byte, 31), idA, 1, 0},
		{"not a uuid", secret, "not-a-uuid", 1, 0},
		{"generation 0", secret, idA, 0, 0},
		{"negative bucket", secret, idA, 1, -1},
	}
	for _, tc := range cases {
		if _, err := BreakGlassCode(tc.secret, tc.id, tc.gen, tc.bucket); err == nil {
			t.Errorf("%s: accepted", tc.name)
		}
	}
}
